{"content":"import {
  createSystem,
  PanelUI,
  PanelDocument,
  UIKitDocument,
  UIKit,
  eq,
  Follower,
  ScreenSpace,
  Mesh,
  BoxGeometry,
  MeshBasicMaterial,
} from '@iwsdk/core';
import type { GameSystem } from './game-system';
import type { AudioSystem } from './audio-system';

type PanelName = 'menu' | 'hud' | 'pause' | 'results' | 'achpanel' | 'settings' | 'stats' | 'tutorial';

export class UISystem extends createSystem({
  menuQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/menu.json')] },
  hudQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/hud.json')] },
  pauseQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/pause.json')] },
  resultsQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/results.json')] },
  achQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/achpanel.json')] },
  settingsQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/settings.json')] },
  statsQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/stats.json')] },
  tutorialQ: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/tutorial.json')] },
}) {
  private game!: GameSystem;
  private audio!: AudioSystem;
  private panels = new Map<PanelName, { entity: any; doc: UIKitDocument }>();
  private activePanel: PanelName = 'menu';
  private achPage = 0;
  private hudEntity: any = null;
  private achievementTimeout: number | null = null;

  setRefs(refs: { game: GameSystem; audio: AudioSystem }) {
    this.game = refs.game;
    this.audio = refs.audio;
  }

  init() {
    this.createPanels();
    this.setupQueries();
  }

  private createPanels() {
    const configs: { name: PanelName; config: string; isHud?: boolean }[] = [
      { name: 'menu', config: './ui/menu.json' },
      { name: 'hud', config: './ui/hud.json', isHud: true },
      { name: 'pause', config: './ui/pause.json' },
      { name: 'results', config: './ui/results.json' },
      { name: 'achpanel', config: './ui/achpanel.json' },
      { name: 'settings', config: './ui/settings.json' },
      { name: 'stats', config: './ui/stats.json' },
      { name: 'tutorial', config: './ui/tutorial.json' },
    ];

    for (const cfg of configs) {
      const backMesh = new Mesh(
        new BoxGeometry(0.001, 0.001, 0.001),
        new MeshBasicMaterial({ visible: false })
      );
      this.scene.add(backMesh);
      const entity = this.world.createTransformEntity(backMesh, { persistent: true });
      entity.addComponent(PanelUI, { config: cfg.config });

      if (cfg.isHud) {
        entity.addComponent(Follower, { target: this.world.player.children[0] || this.world.player });
        const offsetView = entity.getVectorView(Follower, 'offsetPosition');
        if (offsetView) { offsetView[0] = 0; offsetView[1] = -0.3; offsetView[2] = -0.8; }
        entity.addComponent(ScreenSpace, {});
        this.hudEntity = entity;
      } else {
        entity.object3D!.position.set(0, 1.5, -1.5);
      }
    }
  }

  private setupQueries() {
    const qMap: [string, PanelName][] = [
      ['menuQ', 'menu'],
      ['hudQ', 'hud'],
      ['pauseQ', 'pause'],
      ['resultsQ', 'results'],
      ['achQ', 'achpanel'],
      ['settingsQ', 'settings'],
      ['statsQ', 'stats'],
      ['tutorialQ', 'tutorial'],
    ];

    for (const [qName, pName] of qMap) {
      (this.queries as any)[qName].subscribe('qualify', (entity: any) => {
        const doc = PanelDocument.data.document[entity.index] as UIKitDocument;
        if (!doc) return;
        this.panels.set(pName, { entity, doc });
        this.bindPanel(pName, doc);
        this.updatePanelVisibility();
      });
    }
  }

  private bindPanel(name: PanelName, doc: UIKitDocument) {
    const btn = (id: string, fn: () => void) => {
      const el = doc.getElementById(id) as UIKit.Text | undefined;
      el?.addEventListener('click', () => { fn(); this.audio?.playSound('click'); });
    };

    switch (name) {
      case 'menu':
        btn('btn-play', () => { this.game.startGame(); this.showPanel('hud'); });
        btn('btn-settings', () => this.showPanel('settings'));
        btn('btn-tutorial', () => this.showPanel('tutorial'));
        btn('btn-stats', () => { this.updateStatsPanel(); this.showPanel('stats'); });
        btn('btn-achievements', () => { this.updateAchPanel(); this.showPanel('achpanel'); });
        this.updateMenuPanel(doc);
        break;

      case 'pause':
        btn('btn-resume', () => { this.game.resumeGame(); this.showPanel('hud'); });
        btn('btn-quit', () => { this.game.returnToMenu(); this.showPanel('menu'); });
        break;

      case 'results':
        btn('btn-play-again', () => { this.game.startGame(); this.showPanel('hud'); });
        btn('btn-menu', () => { this.game.returnToMenu(); this.showPanel('menu'); });
        break;

      case 'achpanel':
        btn('btn-ach-prev', () => { this.achPage = Math.max(0, this.achPage - 1); this.updateAchPanel(); });
        btn('btn-ach-next', () => { this.achPage = Math.min(1, this.achPage + 1); this.updateAchPanel(); });
        btn('btn-ach-back', () => this.showPanel('menu'));
        break;

      case 'settings':
        btn('btn-color-prev', () => {
          this.game.colorScheme = (this.game.colorScheme + 3) % 4;
          this.game.updatePlayerColor();
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-color-next', () => {
          this.game.colorScheme = (this.game.colorScheme + 1) % 4;
          this.game.updatePlayerColor();
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-sound-toggle', () => {
          this.game.soundEnabled = !this.game.soundEnabled;
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-mode-prev', () => {
          const modes = ['classic', 'speed', 'zen', 'challenge', 'endless'] as const;
          const idx = modes.indexOf(this.game.mode);
          this.game.mode = modes[(idx + 4) % 5];
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-mode-next', () => {
          const modes = ['classic', 'speed', 'zen', 'challenge', 'endless'] as const;
          const idx = modes.indexOf(this.game.mode);
          this.game.mode = modes[(idx + 1) % 5];
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-diff-prev', () => {
          const diffs = ['easy', 'medium', 'hard'] as const;
          const idx = diffs.indexOf(this.game.difficulty);
          this.game.difficulty = diffs[(idx + 2) % 3];
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-diff-next', () => {
          const diffs = ['easy', 'medium', 'hard'] as const;
          const idx = diffs.indexOf(this.game.difficulty);
          this.game.difficulty = diffs[(idx + 1) % 3];
          this.game.savePersistence();
          this.updateSettingsPanel();
        });
        btn('btn-settings-back', () => this.showPanel('menu'));
        this.updateSettingsPanel();
        break;

      case 'stats':
        btn('btn-stats-back', () => this.showPanel('menu'));
        break;

      case 'tutorial':
        btn('btn-tutorial-back', () => this.showPanel('menu'));
        break;
    }
  }

  showPanel(name: PanelName) {
    this.activePanel = name;
    this.updatePanelVisibility();

    if (name === 'results') this.updateResultsPanel();
    if (name === 'menu') this.updateMenuPanel();
    if (name === 'settings') this.updateSettingsPanel();
    if (name === 'stats') this.updateStatsPanel();
    if (name === 'achpanel') this.updateAchPanel();
  }

  private updatePanelVisibility() {
    for (const [name, panel] of this.panels) {
      const visible = name === this.activePanel || (name === 'hud' && this.activePanel === 'hud');
      if (panel.entity.object3D) {
        panel.entity.object3D.visible = visible;
      }
    }
  }

  private setText(panelName: PanelName, id: string, text: string) {
    const panel = this.panels.get(panelName);
    if (!panel) return;
    const el = panel.doc.getElementById(id) as UIKit.Text | undefined;
    el?.setProperties({ text });
  }

  updateHUD() {
    this.setText('hud', 'score-val', `${this.game.score}`);
    this.setText('hud', 'lives-val', `x${this.game.lives}`);
    this.setText('hud', 'wave-val', `Wave ${this.game.wave}`);
    this.setText('hud', 'high-val', `Best: ${this.game.highScore}`);

    if (this.game.mode === 'speed') {
      this.setText('hud', 'timer-val', `${Math.ceil(this.game.speedTimer)}s`);
    } else {
      this.setText('hud', 'timer-val', '');
    }

    if (this.game.currentCombo > 1) {
      this.setText('hud', 'combo-val', `x${this.game.currentCombo}`);
    } else {
      this.setText('hud', 'combo-val', '');
    }
  }

  private updateMenuPanel(doc?: UIKitDocument) {
    const d = doc || this.panels.get('menu')?.doc;
    if (!d) return;
    this.setText('menu', 'high-score', `High Score: ${this.game.highScore}`);
    this.setText('menu', 'mode-display', `Mode: ${this.game.mode.toUpperCase()}`);
  }

  private updateSettingsPanel() {
    this.setText('settings', 'color-val', this.game.getColorName());
    this.setText('settings', 'sound-val', this.game.soundEnabled ? 'ON' : 'OFF');
    this.setText('settings', 'mode-val', this.game.mode.toUpperCase());
    this.setText('settings', 'diff-val', this.game.difficulty.toUpperCase());
  }

  private updateResultsPanel() {
    const won = this.game.state === 'results' && this.game.lives > 0;
    this.setText('results', 'result-title', won ? 'VICTORY!' : 'GAME OVER');
    this.setText('results', 'result-score', `Score: ${this.game.score}`);
    this.setText('results', 'result-waves', `Waves: ${this.game.wavesCleared}`);
    this.setText('results', 'result-accuracy', `Accuracy: ${this.game.getAccuracy()}%`);
    const stars = this.game.getStarRating();
    this.setText('results', 'result-stars', '*'.repeat(stars) + '-'.repeat(3 - stars));
    this.setText('results', 'result-time', `Time: ${Math.floor(this.game.gameTime)}s`);
    if (this.game.score >= this.game.highScore && this.game.score > 0) {
      this.setText('results', 'result-new-high', 'NEW HIGH SCORE!');
    } else {
      this.setText('results', 'result-new-high', '');
    }
  }

  private updateStatsPanel() {
    this.setText('stats', 'stat-games', `Games Played: ${this.game.gamesPlayed}`);
    this.setText('stats', 'stat-wins', `Games Won: ${this.game.totalGamesWon}`);
    this.setText('stats', 'stat-high', `High Score: ${this.game.highScore}`);
    this.setText('stats', 'stat-best-wave', `Best Wave: ${this.game.bestWave}`);
    this.setText('stats', 'stat-kills', `Total Kills: ${this.game.totalKills}`);
    this.setText('stats', 'stat-ufos', `UFOs Hit: ${this.game.totalUFOs}`);
    this.setText('stats', 'stat-shots', `Total Shots: ${this.game.totalShots}`);
    this.setText('stats', 'stat-accuracy', `Accuracy: ${this.game.totalShots > 0 ? Math.round(this.game.totalHits / this.game.totalShots * 100) : 0}%`);
    this.setText('stats', 'stat-streak', `Best Streak: ${this.game.bestStreak}`);
  }

  private updateAchPanel() {
    const all = [
      'First Blood', 'Wave Rider', 'Sharpshooter', 'UFO Hunter',
      'Combo x5', 'Combo x10', 'Wave 5', 'Wave 10',
      'Score 1000', 'Score 5000', 'Score 10000', 'Perfect Wave',
      'UFO Master', 'Survivor', 'Speed Demon', 'Challenge Clear',
      'Marathon', '10 Games', 'Win Streak 3', 'Untouchable',
    ];
    const perPage = 10;
    const start = this.achPage * perPage;
    const page = all.slice(start, start + perPage);

    for (let i = 0; i < perPage; i++) {
      const ach = page[i];
      const unlocked = ach ? this.game.achievements.includes(ach) : false;
      const text = ach ? (unlocked ? `[*] ${ach}` : `[ ] ${ach}`) : '';
      this.setText('achpanel', `ach-${i}`, text);
    }
    this.setText('achpanel', 'ach-page', `${this.achPage + 1}/2`);
    this.setText('achpanel', 'ach-count', `${this.game.achievements.length}/${all.length}`);
  }

  showAchievement(name: string) {
    this.setText('hud', 'ach-notify', `Achievement: ${name}!`);
    if (this.achievementTimeout !== null) {
      clearTimeout(this.achievementTimeout);
    }
    this.achievementTimeout = window.setTimeout(() => {
      this.setText('hud', 'ach-notify', '');
      this.achievementTimeout = null;
    }, 3000) as unknown as number;
    this.audio?.playSound('achievement');
  }

  update() {
    // Check if game ended and we need to show results
    if (this.game.state === 'results' && this.activePanel === 'hud') {
      this.showPanel('results');
    }
  }
}
